export const e9NounsPronounsMCQs: MCQ[] = [
  { id: "e9d-np1", question: "The police dispersed the crowd. The underlined word 'crowd' is a/an ______ noun.", options: ["Countable", "Material", "Collective", "Uncountable"], correctAnswer: 2, explanation: "Crowd = a group of people → Collective noun." },
  { id: "e9d-np2", question: "Some are born great. The underlined word 'Some' is a/an ______ pronoun.", options: ["Possessive", "Indefinite", "Reflexive", "Personal"], correctAnswer: 1, explanation: "Some = non-specific → Indefinite pronoun." },
  { id: "e9d-np3", question: "She faced every calamity of life with patience. 'Patience' is a/an ______ noun.", options: ["Collective", "Abstract", "Countable", "Gerund"], correctAnswer: 1, explanation: "Patience = quality you cannot touch → Abstract noun." },
  { id: "e9d-np4", question: "The moment which is lost is lost forever. 'Which' is a/an:", options: ["Indefinite pronoun", "Reflexive pronoun", "Possessive pronoun", "Relative pronoun"], correctAnswer: 3, explanation: "Which connects clauses → Relative pronoun." },
  { id: "e9d-np5", question: "'Life' is a/an:", options: ["Adjective", "Adverb", "Verb", "Abstract noun"], correctAnswer: 3, explanation: "Life = idea/concept → Abstract noun." },
  { id: "e9d-np6", question: "You will hurt yourself. 'Yourself' is a/an ______ pronoun.", options: ["Indefinite", "Possessive", "Reflexive", "Relative"], correctAnswer: 2, explanation: "Yourself ends in -self → Reflexive pronoun." },
  { id: "e9d-np7", question: "The people who are addicted to drugs. 'Who' is a/an:", options: ["Noun", "Verb", "Relative pronoun", "Possessive pronoun"], correctAnswer: 2, explanation: "Who connects clauses → Relative pronoun." },
];
export const e9NounsPronounsNotes: string[] = [
  "**Abstract Noun:** Feelings, ideas, qualities you cannot touch (e.g., patience, justice, life, merit).",
  "**Collective Noun:** A group of people or things (e.g., crowd, audience, crew, class).",
  "**Reflexive Pronoun:** Ends in -self/-selves (myself, yourself, himself, themselves).",
  "**Relative Pronoun:** Connects clauses (who, which, that, whom, whose).",
  "**Indefinite Pronoun:** Non-specific (some, everybody, someone, anything).",
];

